from pagination import paginate


def test_literal_example_range_page2_size2():
    # Literal issue example: range(1, 8) == [1, 2, 3, 4, 5, 6, 7]
    result = paginate(list(range(1, 8)), 2, 2)
    assert result == [3, 4]
    assert isinstance(result, list)


def test_first_page_one_based():
    assert paginate(list(range(1, 8)), 1, 2) == [1, 2]


def test_last_full_page():
    assert paginate(list(range(1, 8)), 3, 2) == [5, 6]


def test_partial_last_page():
    assert paginate(list(range(1, 8)), 4, 2) == [7]


def test_beyond_last_page_returns_empty_list():
    result = paginate(list(range(1, 8)), 5, 2)
    assert result == []
    assert isinstance(result, list)


def test_empty_input_returns_empty_list():
    result = paginate([], 1, 2)
    assert result == []
    assert isinstance(result, list)


def test_invalid_page_returns_empty_list():
    assert paginate([1, 2, 3], 0, 2) == []
    assert paginate([1, 2, 3], -1, 2) == []


def test_invalid_page_size_returns_empty_list():
    assert paginate([1, 2, 3], 1, 0) == []
    assert paginate([1, 2, 3], 1, -3) == []


def test_page_size_one():
    assert paginate(list(range(1, 8)), 3, 1) == [3]


def test_page_size_larger_than_items():
    assert paginate(list(range(1, 8)), 1, 100) == [1, 2, 3, 4, 5, 6, 7]
    assert paginate(list(range(1, 8)), 2, 100) == []


def test_does_not_mutate_input():
    items = list(range(1, 8))
    snapshot = list(items)
    paginate(items, 2, 2)
    assert items == snapshot
